function unresolvedMachineThreadCount(repoInfo, prNumber, machineLogins) {
    if (typeof github_get_pr_review_threads !== 'function') return -1;
    var lower = [];
    (machineLogins || []).forEach(function (l) {
        if (l) lower.push(String(l).toLowerCase());
